async def act(page):
    """
    Perform a visible site search for 'playbook' and click the second-to-last result.

    Strategy:
    - Try create_curated_collection_by_search(...) first (site-aware helper). If it works,
      proceed to locate role="main" > role="article" children and click the second-to-last.
    - If the helper fails, fall back to a manual, accessibility-role-centric flow that:
      * navigates to 'Sample Page' if present,
      * finds a complementary region or global search input (searchbox/textbox),
      * fills 'playbook', triggers the search via a 'search' button or Enter,
      * waits for role='main' and clicks the second-to-last article's first link (or the article).

    The navigation-causing click is the last action.
    """

    # 1) Try site-aware helper first (required when available)
    helper_succeeded = False
    try:
        # This helper navigates to '/' internally and runs an accessible search flow.
        await create_curated_collection_by_search(page, "playbook", max_results=0, resolve_links=True)
        helper_succeeded = True
    except Exception:
        helper_succeeded = False

    # 2) If helper didn't succeed, perform a manual accessibility-role-centric search flow
    if not helper_succeeded:
        # If a "Sample Page" link exists, navigate there (the accessibility tree shows it on the current page).
        try:
            sample_count = await page.get_by_role("link", name="Sample Page").count()
        except Exception:
            sample_count = 0

        if sample_count > 0:
            await page.get_by_role("link", name="Sample Page").nth(0).click()
            await page.wait_for_load_state("networkidle")

        # Locate complementary region and a search input inside it (role-centric only).
        search_input = None
        try:
            comp_count = await page.get_by_role("complementary").count()
        except Exception:
            comp_count = 0

        if comp_count > 0:
            comp = page.get_by_role("complementary").nth(0)
            # Prefer role=searchbox, else role=textbox inside complementary region
            try:
                sb_count = await comp.get_by_role("searchbox").count()
            except Exception:
                sb_count = 0
            if sb_count > 0:
                search_input = comp.get_by_role("searchbox").nth(0)
            else:
                try:
                    tb_count = await comp.get_by_role("textbox").count()
                except Exception:
                    tb_count = 0
                if tb_count > 0:
                    search_input = comp.get_by_role("textbox").nth(0)
        else:
            # No complementary region; try global searchbox/textbox
            try:
                sb_count = await page.get_by_role("searchbox").count()
            except Exception:
                sb_count = 0
            if sb_count > 0:
                search_input = page.get_by_role("searchbox").nth(0)
            else:
                try:
                    tb_count = await page.get_by_role("textbox").count()
                except Exception:
                    tb_count = 0
                if tb_count > 0:
                    search_input = page.get_by_role("textbox").nth(0)

        if search_input is None:
            # No accessible search input found; abort with an informative exception
            raise Exception("Could not locate an accessible search input to perform the 'playbook' query.")

        # Fill the search term
        try:
            await search_input.fill("playbook")
        except Exception:
            await search_input.click()
            await page.keyboard.type("playbook")

        # Trigger the search. Prefer a button in the complementary region named like 'search', else try global buttons, else press Enter.
        triggered = False
        if comp_count > 0:
            comp = page.get_by_role("complementary").nth(0)
            try:
                btn_count = await comp.get_by_role("button").count()
            except Exception:
                btn_count = 0
            if btn_count > 0:
                # Look for a button whose visible name contains 'search' (case-insensitive)
                target_btn = None
                for i in range(btn_count):
                    btn = comp.get_by_role("button").nth(i)
                    try:
                        name = (await btn.inner_text()).strip()
                    except Exception:
                        name = ""
                    if "search" in name.lower():
                        target_btn = btn
                        break
                if target_btn is None:
                    target_btn = comp.get_by_role("button").nth(0)
                await target_btn.click()
                triggered = True

        if not triggered:
            # Try global buttons with 'search' in their name
            try:
                global_btn_count = await page.get_by_role("button").count()
            except Exception:
                global_btn_count = 0
            target_btn = None
            for i in range(global_btn_count):
                btn = page.get_by_role("button").nth(i)
                try:
                    name = (await btn.inner_text()).strip()
                except Exception:
                    name = ""
                if "search" in name.lower():
                    target_btn = btn
                    break
            if target_btn is not None:
                await target_btn.click()
                triggered = True

        if not triggered:
            # Final fallback: press Enter in the input
            await search_input.press("Enter")

    # 3) Wait for role="main" to contain results
    main = page.get_by_role("main")
    try:
        await main.wait_for(state="visible", timeout=5000)
    except Exception:
        # Fallback to networkidle
        await page.wait_for_load_state("networkidle")

    # 4) Collect article children and click the second-to-last result
    articles = main.get_by_role("article")
    articles_count = await articles.count()

    if articles_count == 0:
        raise Exception("No article results found after searching for 'playbook'.")

    idx = articles_count - 2 if articles_count >= 2 else 0
    target_article = articles.nth(idx)

    # Prefer to click the first link inside the article using the full parent->child path
    try:
        links_count = await target_article.get_by_role("link").count()
    except Exception:
        links_count = 0

    if links_count > 0:
        await main.get_by_role("article").nth(idx).get_by_role("link").nth(0).click()
    else:
        # Fallback: click the article container itself
        await main.get_by_role("article").nth(idx).click()

